'use strict';

// MODULES //

var isArray = require( '@stdlib/assert/is-array' );
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var copy = require( '@stdlib/utils/copy' );
var format = require( '@stdlib/string/format' );
var parse = require( '@stdlib/utils/json-pointer/parse' );
var formatPointer = require( '@stdlib/utils/json-pointer/format' );
var get = require( '@stdlib/utils/json-pointer/get' );
var setIn = require( './../../../_lib/set_in.js' );
var insertIn = require( './../../../_lib/insert_in.js' );


// MAIN //

/**
* Applies a JSON Patch `add` operation to a document immutably.
*
* ## Notes
*
* -   Implements the `add` operation per RFC 6902 §4.1.
* -   If `path` targets an existing object member, the member's value is replaced.
* -   If `path` targets a nonexistent object member, the member is added.
* -   If `path` targets an array element, the value is inserted before that index.
* -   If `path` uses `-` on an array, the value is appended.
* -   If `path` is `""` (root), the entire document is replaced by `value`.
* -   The target location's containing object/array must exist.
* -   The incoming `value` is deep-cloned to prevent reference sharing.
* -   Returns a new document; the original is not modified (structural sharing).
*
* @param {(Object|Array)} document - source JSON document
* @param {string} path - JSON Pointer string
* @param {*} value - value to add
* @throws {TypeError} first argument must be an object or array
* @throws {TypeError} second argument must be a string
* @throws {Error} path must reference a valid location
* @returns {(Object|Array)} new document with the value added
*
* @example
* var doc = { 'foo': [ 1, 2, 3 ] };
* var out = add( doc, '/foo/-', 4 );
* // returns { 'foo': [ 1, 2, 3, 4 ] }
*
* @example
* var doc = { 'foo': 'bar' };
* var out = add( doc, '/baz', 'qux' );
* // returns { 'foo': 'bar', 'baz': 'qux' }
*
* @example
* var doc = { 'foo': [ 1, 2, 3 ] };
* var out = add( doc, '/foo/1', 99 );
* // returns { 'foo': [ 1, 99, 2, 3 ] }
*/
function add( document, path, value ) {
	var parentPointer;
	var cloned;
	var tokens;
	var parent;

	if ( !isPlainObject( document ) && !isArray( document ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be an object or an array. Value: `%s`.', document ) );
	}
	if ( !isString( path ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be a string. Value: `%s`.', path ) );
	}

	tokens = parse( path );
	cloned = copy( value );

	// Root replacement:
	if ( tokens.length === 0 ) {
		return cloned;
	}

	// Determine the parent container to decide between insert (array) and set (object):
	parentPointer = formatPointer( tokens.slice( 0, -1 ) );
	parent = get( document, parentPointer );

	// If the parent is an array, this is an insert operation (insert before index / append):
	if ( isArray( parent ) ) {
		return insertIn( document, tokens, cloned );
	}

	// If the parent is an object, this is a set operation (add or replace the property):
	return setIn( document, tokens, cloned );
}


// EXPORTS //

module.exports = add;
